const body = ($input.first().json.body) || $input.first().json || [];
const pages = Array.isArray(body) ? body : (body.pages || []);
const all = [];
(function flat(arr){ for (const p of (arr||[])) { all.push(p); if (p.pages) flat(p.pages); } })(pages);
const page = all.find(p => p.id === 'q7wz-44812');
const rules_md = (page && page.content) ? String(page.content) : '';
const rules_present = !!rules_md && rules_md.trim().length > 50;
const date_edited = page ? (page.date_edited || page.date_updated || null) : null;
return [{ json: { rules_md, rules_present, date_edited, page_found: !!page } }];

const inp = $input.first().json;
const rules = inp.rules_md;
const sha = inp.rules_sha256;
const CONV = 20;

const framing = [
  '# Tożsamość i kontrakt techniczny (stały)',
  'Jesteś uniwersalnym agentem Haxe uruchamianym do jednego konkretnego zadania w ClickUp. Poniżej masz globalne zasady firmy (utrzymywane w ClickUp jako jedyne źródło prawdy) oraz stały kontrakt techniczny formatu odpowiedzi. Szczegóły zadania, preferencje osoby zlecającej, komentarze i ewentualne obrazy wejściowe otrzymasz w wiadomości użytkownika.'
].join('\n');

const contract = [
  '# Format odpowiedzi (kontrakt techniczny — OBOWIĄZKOWY)',
  'Swoją FINALNĄ odpowiedź dostarczasz WYŁĄCZNIE przez JEDNO wywołanie narzędzia deliver_output, na samym końcu pracy. Cokolwiek napiszesz poza tym wywołaniem (w treści wiadomości) NIE dotrze do odbiorcy.',
  'deliver_output ma jeden parametr: markdown — CAŁA Twoja odpowiedź jako zwykły tekst markdown po polsku (nagłówki, listy, tabele, pogrubienia, linki). Pisz naturalnie, tak jak piszesz odpowiedź dla człowieka. NIE umieszczaj tu tablicy JSON, obiektów ani „bloków” — to ma być czysta proza markdown.',
  'OBRAZY wstawiasz INLINE w treści markdown, w miejscu, w którym mają się pojawić, standardową składnią obrazu markdown:',
  '  - Obraz WYGENEROWANY: najpierw wywołaj generate_image (zwróci file_id), potem wstaw w markdown ![krótki opis](file_id) — DOKŁADNIE to file_id.',
  '  - Obraz ISTNIEJĄCY (załącznik zadania): ![opis](ref) — użyj wartości ref z sekcji „Załączone obrazy”.',
  'Przeplatanie tekstu i obrazów wychodzi samo — obraz renderuje się dokładnie tam, gdzie wstawisz ![](…) w tekście. Nie musisz nic „układać w kolejności” ani wołać dodatkowych narzędzi.',
  'Zasady:',
  '- Treść pisz jako zwykły markdown. Zachowuj miękką strukturę, pomijając puste sekcje: „## Wyniki”, „## Pytania do zlecającego”, „## Decyzje i kompromisy”, a na końcu „## Sugestie do procesu”.',
  '- NOWY obraz tworzysz WYŁĄCZNIE wywołując narzędzie generate_image (patrz sekcja Narzędzia); dopiero potem wstawiasz zwrócone file_id w markdown przez ![opis](file_id). Samo wywołanie generate_image NIE pokazuje obrazu — musisz go wstawić w treści. NIGDY nie wstawiaj file_id, którego narzędzie nie zwróciło w tej sesji.',
  '- Pliki biurowe (xlsx, docx, pptx, pdf): twórz je odpowiednią umiejętnością i ZAPISZ do wyjść sesji. System dołączy KAŻDY taki plik jako załącznik do komentarza ClickUp AUTOMATYCZNIE — nie wstawiasz go przez ![](…) i nie podajesz file_id. W treści WSPOMNIJ o pliku (nazwa + co zawiera), aby odbiorca wiedział, co dostał. Jeśli w pliku biurowym osadzasz obraz wygenerowany przez generate_image, NAJPIERW pobierz jego bajty z download_url (patrz sekcja Narzędzia), a potem osadź — wygenerowanego obrazu nie osadzisz przez sam file_id.',
  '- Jeśli obrazy ani pliki nie są potrzebne, wywołaj deliver_output z samym tekstem markdown. Nawet trywialna odpowiedź MUSI przejść przez deliver_output — to jedyny kanał dostarczenia.',
  '- Jeśli uznasz, że zadanie nie jest dla AI, odmawiasz jego wykonania lub nie możesz go ukończyć — i tak MUSISZ dostarczyć tę konkluzję (powód i ewentualną rekomendację) jako tekst markdown w deliver_output. NIGDY nie kończ pustym deliver_output bez treści ani plików: pusty wynik jest traktowany jako niedostarczenie i NIE trafia do odbiorcy.'
].join('\n');

const toolsDesc = [
  '# Narzędzia i umiejętności',
  '- Wyszukiwanie w sieci (web_search) jest wbudowane — używaj go, gdy zadanie wymaga aktualnych lub zewnętrznych informacji. Korzystaj z równoległych zapytań i syntezy; NIGDY nie umieszczaj danych osobowych w treści zapytania.',
  '- Generowanie obrazów: aby utworzyć NOWY obraz, WYWOŁAJ narzędzie generate_image z parametrami { prompt (opis obrazu), clickup_task_id (OBOWIĄZKOWE — skopiuj DOKŁADNIE identyfikator zadania podany w wiadomości pod nagłówkiem „Identyfikator zadania ClickUp (clickup_task_id)”; bez niego koszt obrazu nie zostanie przypisany do zadania), aspect_ratio (np. "1:1"), opcjonalnie reference_file_ids (gdy chcesz wierności realnemu produktowi z załączonego zdjęcia), opcjonalnie size "SZERxWYS" w pikselach TYLKO gdy użytkownik prosi o konkretną rozdzielczość }. Narzędzie wykona się w tle i zwróci file_id; ten file_id wstaw w treści markdown wywołania deliver_output jako ![krótki opis](file_id), aby obraz został dostarczony inline. Generuj obraz tylko gdy zadanie tego wymaga. Narzędzie zwraca dla KAŻDEGO obrazu file_id ORAZ download_url (krótkotrwały podpisany link do pobrania bajtów obrazu). Aby pokazać obraz INLINE w odpowiedzi — wstaw ![opis](file_id) w tekście markdown. Aby OSADZIĆ obraz WEWNĄTRZ pliku biurowego (pptx/docx/xlsx/pdf) — pobierz bajty z download_url tego obrazu do sesji (np. narzędziem bash/skryptem), a potem osadź obraz w dokumencie; sam file_id NIE wystarcza do osadzenia w pliku biurowym, bo plik z Files API nie jest pobieralny. Jeśli pobranie z download_url się nie powiedzie, użyj grafiki wektorowej zamiast wygenerowanego obrazu i kontynuuj.',
  '- Umiejętności dokumentowe (docx, xlsx, pptx, pdf): używaj ich, gdy zadanie wymaga wygenerowania pliku biurowego, i zapisz wynik do wyjść sesji; system dołączy go automatycznie jako załącznik do komentarza (nie podawaj file_id pliku w odpowiedzi).', '- Wyszukiwanie powiązanego kontekstu w ClickUp (zakres uprawnień osoby zlecającej): jeśli masz dostępne narzędzia clickup_* (np. clickup_search, clickup_filter_tasks, clickup_get_task, clickup_get_task_comments, clickup_get_workspace_hierarchy, clickup_get_document_pages, clickup_get_custom_fields), używaj ich z własnej inicjatywy, aby znaleźć POWIĄZANE zadania, dokumenty, komentarze i pola niestandardowe istotne dla bieżącego zadania. Te narzędzia są ograniczone do uprawnień osoby, która Cię uruchomiła (widzisz wyłącznie to, co ona widzi w ClickUp) i służą wyłącznie do ODCZYTU — nie twórz ani nie modyfikuj niczego w ClickUp. Kontekst samego zadania wyzwalającego masz już w wiadomości; narzędzia clickup_* służą do szukania DODATKOWYCH powiązanych informacji. Jeśli narzędzia clickup_* nie są dostępne, pracuj na podstawie dostarczonego kontekstu i nie zgłaszaj tego jako błędu.', '- Ekstrakcja zawartości załączników (extract_clickup_task): narzędzia clickup_* zwracają opisy, komentarze i pola, ale NIE treść załączonych plików. Gdy powiązane zadanie ma załączniki (dokumenty, obrazy), których treść jest istotna dla bieżącego zadania, WYWOŁAJ extract_clickup_task z { clickup_task_id } tego zadania — zwróci wyekstrahowaną treść dokumentów (tekst) oraz obrazy (jako wizję), wyłącznie w zakresie Twoich uprawnień. Najpierw ROZPOZNAJ przez clickup_* co warto pobrać, potem ekstrahuj tylko istotne zadania (nie ekstrahuj masowo). Jeśli nie masz dostępu do zadania, narzędzie zwróci informację o braku dostępu — uszanuj to.', '- KONTEKST SAMEGO ZADANIA WYZWALAJACEGO pobierasz na zadanie (nie ma go juz w calosci w wiadomosci - masz tylko: preferencje osoby, wiadomosc wywolujaca, wage zadania, tytul zadania oraz ewentualne obrazy wejsciowe; OPIS zadania nie jest juz w wiadomosci - pobierz go przez get_task_details, gdy potrzebujesz specyfikacji). Piec narzedzi ograniczonych do TEGO zadania (system podaje identyfikator, nie mozesz go zmienic): get_task_comments (komentarze i odpowiedzi w watkach; opcjonalnie { limit, since }); get_parent_chain (tytuly i opisy zadan nadrzednych; opcjonalnie { depth }); list_attachments (lista zalacznikow: attachment_id, nazwa, typ, rozmiar - bez tresci); get_attachment ({ attachment_id } - tresc JEDNEGO zalacznika: dokument jako tekst, obraz jako wizja); get_task_details (zwraca tytul, opis/specyfikacje i status zadania wyzwalajacego - wywolaj gdy do wykonania zadania potrzebujesz pelnego opisu zadania). Strategia: pobieraj TYLKO to, czego wymaga zadanie - przy trywialnym pytaniu nie wywoluj zadnego z nich. Po zalacznik: najpierw list_attachments, potem get_attachment dla wybranego attachment_id. Zalaczniki ZIP rozwijaja sie w list_attachments na liste plikow wewnetrznych (kazdy z attachment_id w formacie "<zip>:<indeks>"); aby pobrac JEDEN plik z archiwum, podaj jego zagniezdzony attachment_id do get_attachment (nie pobierasz wtedy calego archiwum, tylko ten jeden plik). Te cztery narzedzia dotycza WYLACZNIE zadania wyzwalajacego; do POWIAZANYCH innych zadan uzywaj narzedzi clickup_* (zakres uprawnien osoby) oraz extract_clickup_task.', '- OBRAZY WEJSCIOWE zadania (sekcja „Załączone obrazy” w wiadomości): na tej sesji NIE są automatycznie przekazane jako wizja — masz tylko ich listę (ref + nazwa). Aby ZOBACZYĆ taki obraz, wywołaj get_attachment z jego attachment_id (= wartość ref). Ale aby WSTAWIĆ go do odpowiedzi inline przez ![opis](ref) albo użyć jako reference_file_ids w generate_image, podaj wartość ref WPROST z listy — to działa bez pobierania (get_attachment jest potrzebny tylko gdy sam musisz zobaczyć treść obrazu).'
].join('\n');

const provenance = '<!-- HAXE-AGENT-PROVENANCE rules_sha256=' + sha + ' conventions_version=' + CONV + ' source=clickup:q7wz-44812 -->';

const system = [framing, '', '# Globalne zasady działania agentów (źródło: ClickUp — jedyne źródło prawdy)', '', rules, '', contract, '', toolsDesc, '', provenance].join('\n');

// ADR-055 (Block 5.3): generowanie obrazów to teraz narzędzie na samodzielnie hostowanym serwerze MCP
// (haxe_image), a nie narzędzie custom po stronie klienta. mcp_servers deklaruje endpoint BEZ pola auth —
// bearer jest dołączany per sesję przez Anthropic Vault (config.image_mcp_vault_id) w Execute Agent Session (v1).
// Sparowany mcp_toolset z permission_policy=always_allow pozwala harnessowi wywołać generate_image
// w-harnessie (agent.mcp_tool_use), więc obraz nigdy nie wchodzi w pętlę pause/resume.
// CONV=3 (Block 6): kontrakt obrazów poprawiony — agent MUSI wywołać generate_image i odwołać się do
// zwróconego file_id (zamiast emitować blok generate z promptem, który na lane managed nie jest realizowany). ADR-054 (Block 3): drugi serwer MCP 'clickup' (mcp.clickup.com/mcp) + sparowany mcp_toolset READ-ONLY (default_config.enabled=false, dozwolone tylko narzędzia odczytu/discovery przez configs) — token MCP-OAuth dołączany per sesję z Anthropic Vault (clickup_mcp_vault_id) w Execute Agent Session; brak czytelnego dla OAuth zakresu read-only, więc read-only egzekwowany allowlistą. Każde dozwolone narzędzie ma własne permission_policy always_allow (API domyślnie ustawia always_ask na default_config). CONV=5 wymusza re-sync. CONV=7 (2026-06-24): wzmocniono zakaz tekstu/preambuly poza tablica blokow — model na zadaniu 869dux9ne dodal zdanie wprowadzajace przed [...], przez co render odrzucil blok obrazu (parse-fallback). CONV=8 (2026-06-24, ADR-057 follow-up): generate_image zyskuje OBOWIAZKOWY parametr clickup_task_id (agent kopiuje id zadania z naglowka wiadomosci) — jedyny kanal atrybucji kosztu obrazu na sciezce MCP (n8n MCP Server Trigger nie udostepnia naglowkow/ciala requestu handlerowi, Block 5.1). CONV=9 (2026-06-25, ADR-061 Block 2): zarejestrowano cztery narzedzia ogona zadania wyzwalajacego (get_task_comments, get_parent_chain, list_attachments, get_attachment) obslugiwane przez Triggering Task Tail Handler (v1) na tokenie bota + sterowanie; floor lane managed nie zawiera juz watku komentarzy, cial zadan nadrzednych ani tekstu zalacznikow (Block 1), wiec agent pobiera je na zadanie tymi narzedziami. CONV=10 (2026-06-26, ADR-061 Block 2b): obrazy WEJSCIOWE zadania sa teraz leniwe na lane managed — floor je listuje (sekcja Zalaczone obrazy), ale NIE laduje jako wizje (input_images_json=[] w Execute Agent Session); agent wola get_attachment by zobaczyc obraz, a embed_input/reference_file_ids dzialaja wprost z wartosci ref. CONV=11 (2026-06-26, ADR-061 Block 2c): list_attachments rozwija archiwa ZIP na pliki wewnetrzne (attachment_id "<zip>:<indeks>"), a get_attachment pobiera pojedynczy plik z archiwum po tym zagniezdzonym id (progresywne ujawnianie ZIP zamiast zrzutu calego archiwum). CONV=12 (2026-06-26, ADR-061 Block 2c follow-on): opis zadania nie jest juz ladowany eager w floor lane managed - agent pobiera go nowym narzedziem get_task_details (tytul zostaje w floor); tail handler list_attachments czyta limity ZIP z config (live). CONV=14 (2026-06-27, ADR-063 Block 5): kontrakt formatu odpowiedzi przelaczony z free-text tablicy JSON na wywolanie narzedzia deliver_output (strukturalny kanal dostarczenia — parsowanie po stronie renderera znika); dodano typ bloku doc (filename) do umieszczania/podpisywania plikow biurowych; render-agent-output i image-resolver konsumuja output_blocks zamiast parseBlockArray. Zob. ADR-063. CONV=15 (2026-06-27, ADR-063 amendment): do opisu pola blocks dodano jawna instrukcje 'Przekaż blocks jako tablicę JSON, nie jako string' — Sonnet czasem serializowal blocks jako string JSON wewnatrz wywolania deliver_output, przez co kapter (Poll Round / Parse Response) odczytywal pusta tablice i render dawal pusty komentarz; kaptery teraz koercuja string->tablice, a delivered+pusto odpala WARN output-adapter/deliver-output-empty. CONV=16 (2026-06-30, ADR-067 Block 3): generate_image zwraca teraz dla kazdego obrazu download_url (krotkotrwaly podpisany link do bajtow w buckecie agent-output-images) obok file_id; kontrakt instruuje agenta, by do OSADZENIA obrazu w pliku biurowym (pptx/docx/xlsx/pdf) pobral bajty z download_url do sesji (Files API purpose=agent nie jest pobieralny), a inline nadal po file_id; fallback przy nieudanym pobraniu -> grafika wektorowa. CONV=19 (2026-07-17, ADR-072 Block 2): kontrakt dostarczania przelaczony z pojedynczego deliver_output({blocks:[...]}) na PLASKIE-SKALARNE wywolania — deliver_output(markdown) jako sygnal ZAKONCZENIA + osobne attach_text/attach_generated_image/attach_input_image, bez zadnej zagniezdzonej tablicy. Powod: Sonnet czasem serializowal tablice blocks do stringa i recznie (blednie) ja escapowal na polskiej prozie (niezaescapowany " w „..."), co wracalo do reczno-parsowania modelowego JSON-a (klasa bledu z ADR-063 amend./ADR-071 — jsonrepair, sanitizeStrayValueQuotes). Plaskie skalary usuwaja container do zserializowania, wiec gwarancja escapingu per-string z API pokrywa cala proze i klasa bledu znika strukturalnie. Usunieto typ bloku doc (pliki biurowe dolaczane autorytatywnie z wyjsc sesji, renderer i tak pomijal bloki doc). session-waiter sklada bloki z dziennika zdarzen sesji (assembleFlatBlocks, services/session-waiter/lib/deliver-blocks.mjs), zachowujac przeplatanie po polu order. Zob. ADR-072. CONV=20 (2026-07-17, ADR-072 amendment): kontrakt przelaczony z segmentow attach_* (model ich NIE uzywal — na tescie 869e5wm5u Sonnet zignorowal attach_generated_image/attach_text i wypisal stara tablice blokow do markdown, obraz osierocony, 0 alertow) na NATYWNY markdown: deliver_output(markdown) to cala odpowiedz jako proza, obrazy inline przez ![opis](file_id) (z generate_image) lub ![opis](ref) (zalacznik). Usunieto narzedzia attach_text/attach_generated_image/attach_input_image. Managed agenci odpowiadaja tak, jak sa zaprojektowani (final message), zamiast walczyc z priorem modelu przez obcy protokol wielowywolaniowy. session-waiter parsuje markdown -> bloki po ![](...) i zglasza WARN przy degradacji (tablica-JSON-w-markdown, osierocony obraz) — services/session-waiter/lib/deliver-blocks.mjs. Kontener zagniezdzony dalej nie istnieje (klasa misescape z ADR-063/071 pozostaje martwa). Zob. ADR-072 (amended).
const mcp_servers = [ { type: 'url', url: 'https://agents.skalus.com/mcp/haxe-image-gen', name: 'haxe_image' }, { type: 'url', url: 'https://mcp.clickup.com/mcp', name: 'clickup' } ];

const extract_clickup_task_tool = { type: 'custom', name: 'extract_clickup_task', description: 'Pobiera i ekstrahuje tresc zalacznikow zadania ClickUp (dokumenty -> tekst, obrazy -> wizja), w zakresie uprawnien osoby ktora uruchomila agenta. Uzyj po znalezieniu powiazanego zadania narzedziami clickup_*, gdy tresc jego zalacznikow jest istotna (narzedzia clickup_* nie zwracaja tresci plikow). Zadanie spoza Twoich uprawnien -> zwroci brak dostepu (nie obchodz tego). Tylko odczyt.', input_schema: { type: 'object', properties: { clickup_task_id: { type: 'string', description: 'Identyfikator zadania ClickUp, ktorego zalaczniki maja zostac wyekstrahowane.' } }, required: ['clickup_task_id'] } };
const deliver_output_tool = { type: 'custom', name: 'deliver_output', description: 'Sygnał ZAKOŃCZENIA i dostarczenie FINALNEJ odpowiedzi. Wywołaj DOKŁADNIE RAZ, na samym końcu pracy. Parametr markdown to CAŁA odpowiedź jako zwykły tekst markdown po polsku; obrazy wstawiaj INLINE w treści składnią ![opis](file_id) (file_id z generate_image) lub ![opis](ref) (załącznik wejściowy). NIE przekazuj tablicy JSON ani obiektów-bloków — tylko prozę markdown.', input_schema: { type: 'object', properties: { markdown: { type: 'string', description: 'CAŁA finalna odpowiedź jako zwykły markdown po polsku (nagłówki, listy, tabele, pogrubienia, linki). Obrazy wstawiaj INLINE składnią ![opis](file_id) — file_id zwrócone przez generate_image dla nowego obrazu, albo ref załącznika z sekcji „Załączone obrazy” dla istniejącego. NIE umieszczaj tu tablicy JSON ani obiektów-bloków; to ma być czysta proza markdown.' } } } };
const tools = [
